<script setup>
import {t} from './i18n.js';
import {computed,ref} from 'vue';
import {administer} from './device-api.js';
import {downloadFile,downloadName} from './download.js';
import {timestamp} from './health.js';
const props=defineProps({dashboard:Object});const emit=defineEmits(['changed']);
const password=ref(''),repeat=ref(''),file=ref(''),fileName=ref(''),summary=ref(null),cursor=ref(null),confirmation=ref(''),busy=ref(false),error=ref(''),message=ref('');
const validPassword=computed(()=>[...password.value].length>=12 && new TextEncoder().encode(password.value).length<=1024);
function invalidate(){summary.value=null;cursor.value=null;confirmation.value='';}
async function selected(event){invalidate();file.value='';fileName.value='';error.value='';const selected=event.target.files?.[0];if(!selected)return;if(selected.size>24*1024*1024){error.value=t("Die Datei darf höchstens 24 MiB groß sein.");return;}file.value=await selected.text();fileName.value=selected.name;}
async function perform(action){busy.value=true;error.value='';message.value='';try{
  const operation={action,password:password.value};
  if(action!=='backup_export')operation.file=file.value;
  if(action==='backup_restore'){operation.confirm=true;operation.expected_audit=cursor.value;}
  const response=await administer(props.dashboard,operation);
  if(action==='backup_export'){downloadFile(response.file,downloadName('hmbackup'),'application/octet-stream');message.value=t("Verschlüsselte Sicherung zum Download bereitgestellt. Bewahre das Passwort getrennt davon auf.");password.value='';repeat.value='';invalidate();emit('changed');}
  else if(action==='backup_inspect'){summary.value=response.summary;cursor.value=response.expected_audit;}
  else{message.value=response.message;password.value='';repeat.value='';file.value='';fileName.value='';invalidate();emit('changed');}
}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><section class="panel device-editor backup-settings"><header><div><h2>{{t("Sicherung & Wiederherstellung")}}</h2><p class="form-note">{{t("Eine verschlüsselte Datei für Geräte, Zugangsdaten, Zertifikate, Einstellungen, Alarmzustände und Protokolle. Unabhängig von Hyper Backup.")}}</p></div></header><fieldset :disabled="busy"><label>{{t("Sicherungspasswort")}}<input v-model="password" type="password" autocomplete="new-password" maxlength="1024" @input="invalidate"><small>{{t("Mindestens 12 Zeichen (UTF-8). Das Passwort wird nicht gespeichert und lässt sich nicht zurücksetzen.")}}</small></label><div class="form-columns"><div><h3>{{t("Neue Sicherung")}}</h3><label>{{t("Passwort wiederholen")}}<input v-model="repeat" type="password" autocomplete="new-password" maxlength="1024"></label><button class="primary" :disabled="!validPassword || password!==repeat" @click="perform('backup_export')">{{t("Verschlüsselte Sicherung herunterladen")}}</button><p class="form-note">{{t("Enthält auch gespeicherte Geräte- und SMTP-Passwörter. Der lokale Hauptschlüssel wird nicht exportiert. Derzeit bis 16 MiB Sicherungsinhalt.")}}</p></div><div><h3>{{t("Bestehende Sicherung")}}</h3><label>{{t("Sicherungsdatei")}}<input type="file" accept=".hmbackup" @change="selected"></label><p v-if="fileName">{{fileName}}</p><button class="refresh" :disabled="!validPassword || !file" @click="perform('backup_inspect')">{{t("Datei und Passwort prüfen")}}</button><div v-if="summary" class="maintenance-confirm"><strong>{{t("Dateiformat und Passwort geprüft")}}</strong><p>Version {{summary.version}} · {{timestamp(summary.created)}}<br>{{summary.devices}} {{t("Geräte ·")}} {{summary.alarms}} {{t("gespeicherte Zustände ·")}} {{summary.events}} {{t("Ereignisse")}}</p><p>{{t("Ersetzt den aktuellen Gerätebestand, Einstellungen, Alarmzustände und Ereignisse. Das bestehende Änderungsprotokoll bleibt erhalten und wird ergänzt. Ausstehende Sendungen der Sicherung werden storniert. Alle wiederhergestellten Geräte und automatischen Benachrichtigungen bleiben pausiert; prüfe sie anschließend und aktiviere sie einzeln. Sichere zuvor bei Bedarf den aktuellen Stand.")}}</p><label>{{t("Zur Bestätigung WIEDERHERSTELLEN eingeben")}}<input v-model="confirmation" autocomplete="off"></label><button class="danger" :disabled="confirmation!==t(&quot;WIEDERHERSTELLEN&quot;)" @click="perform('backup_restore')">{{t("Datenbestand ersetzen und wiederherstellen")}}</button></div></div></div></fieldset><p v-if="busy" role="status">{{t("Sicherung wird verarbeitet …")}}</p><p v-if="message" role="status">{{message}}</p><p v-if="error" class="error" role="alert">{{error}}</p><p class="form-note">{{t("Die Datei enthält keine DSM-Benutzer oder DSM-Passwörter. Nach einer Übertragung auf ein anderes NAS gelten dessen DSM-Anmeldung und Berechtigungen. Export und Wiederherstellung werden im Änderungsprotokoll erfasst.")}}</p></section></template>
